package main

const htmlPage = `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SSH Proxy для Keenetic</title><style>
:root{font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:#17253a;background:#f0f4f8}*{box-sizing:border-box}body{margin:0;padding:32px 16px}.wrap{max-width:920px;margin:auto}h1{font-size:28px;margin:0}h2{font-size:19px;margin:0 0 18px}p{line-height:1.5;color:#516174}.sub{margin:7px 0 24px}.card{background:#fff;border:1px solid #e0e8f0;border-radius:14px;padding:22px;margin:16px 0;box-shadow:0 4px 20px #253d5b0b}.top{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.badge{border-radius:30px;padding:7px 13px;background:#edf1f5;color:#405168;font-weight:600}.badge.connected{background:#dcf8ed;color:#07704a}.badge.retrying,.badge.error{background:#fff0e8;color:#a74613}.grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;color:#35475e;font-size:14px;font-weight:600;margin:12px 0 6px}input,select,textarea{width:100%;padding:11px;border:1px solid #cbd6e2;border-radius:8px;background:#fff;font:inherit;color:#152238}textarea{min-height:84px;resize:vertical;font-family:monospace;font-size:12px}.check{display:flex;gap:9px;align-items:center;margin:14px 0;font-size:14px}.check input{width:auto}.buttons{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}button{border:0;border-radius:8px;padding:10px 17px;background:#1072d3;color:#fff;font:600 14px system-ui;cursor:pointer}button.secondary{background:#eaf1f8;color:#254a6a}button.danger{background:#fff0ee;color:#a13b31}button:disabled{opacity:.45;cursor:default}.hint{font-size:13px;line-height:1.45;color:#607086}.error{white-space:pre-wrap;color:#a33e2b;font-size:13px}.success{color:#08744b}.mono{font-family:monospace;overflow-wrap:anywhere}.key{border:1px solid #e0e8f0;border-radius:8px;padding:10px;margin:8px 0}.key button{margin-left:8px}.hide{display:none}@media(max-width:620px){.grid,.two{grid-template-columns:1fr}body{padding:18px 10px}.card{padding:16px}}
</style></head><body><main class="wrap"><h1>SSH Proxy</h1><p class="sub">Управление SSH-туннелем и локальным SOCKS5 для Keenetic</p>
<section class="card"><div class="top"><h2 style="margin:0">Подключение</h2><span id="status" class="badge">Загрузка…</span></div><p id="lastError" class="error"></p><div class="buttons"><button id="start" type="button">Подключить</button><button id="stop" type="button" class="danger">Отключить</button></div><p class="hint">SOCKS5 работает на 127.0.0.1 указанного порта. Для передачи трафика используйте клиент прокси Keenetic.</p></section>
<section class="card"><h2>Профиль SSH</h2><div class="grid"><div><label for="host">Хост или IP</label><input id="host" autocomplete="off" placeholder="example.com"></div><div><label for="port">Порт SSH</label><input id="port" type="number" min="1" max="65535" value="22"></div><div><label for="socksPort">Порт SOCKS5</label><input id="socksPort" type="number" min="1024" max="65535" value="1080"></div></div>
<div class="two"><div><label for="user">Пользователь SSH</label><input id="user" autocomplete="off"></div><div><label for="auth">Авторизация</label><select id="auth"><option value="password">Пароль</option><option value="key">Закрытый ключ</option></select></div></div>
<div id="passwordBlock"><label for="password">Пароль SSH</label><input id="password" type="password" autocomplete="new-password" placeholder="Введите пароль"></div>
<div id="keyBlock" class="hide"><label for="privateKey">Закрытый ключ OpenSSH</label><textarea id="privateKey" placeholder="-----BEGIN OPENSSH PRIVATE KEY-----"></textarea><label for="keyPassphrase">Пароль к ключу, если есть</label><input id="keyPassphrase" type="password" autocomplete="new-password"><label for="certificate">Сертификат OpenSSH, если используется</label><textarea id="certificate" placeholder="ssh-ed25519-cert-v01@openssh.com ..."></textarea></div><p class="hint">Сохранённые секреты повторно не показываются. Пустое поле сохраняет прежнее значение. Они хранятся на накопителе с правами root.</p>
<h2 style="margin-top:26px">Проверка сервера</h2><p class="hint">Получите ключ, сравните отпечаток с тем, который вы получили от администратора сервера по независимому каналу, и введите его ниже.</p><button id="scan" type="button" class="secondary">Получить ключи сервера</button><div id="keys"></div><label for="hostKey">Выбранный открытый ключ сервера</label><textarea id="hostKey" placeholder="ssh-ed25519 AAAA..."></textarea><label for="fingerprint">Проверенный отпечаток SHA256</label><input id="fingerprint" autocomplete="off" placeholder="SHA256:..."><p class="hint">Если ключ сервера изменится, соединение будет отклонено.</p>
<label class="check"><input id="autostart" type="checkbox"> Подключаться после запуска роутера</label><label class="check"><input id="reconnect" type="checkbox" checked> Переподключаться при обрыве</label><div class="buttons"><button id="save" type="button">Сохранить настройки</button></div><p id="message" class="error"></p></section>
<p class="hint">Этот интерфейс работает отдельно от штатной панели Keenetic. Если SOCKS подключён к нему локально, не открывайте порт SOCKS наружу.</p></main>
<script>
const $=id=>document.getElementById(id);const fields=['host','port','socksPort','user','auth','password','privateKey','keyPassphrase','certificate','hostKey','fingerprint'];let loaded=false;
const labels={stopped:'Отключено',connecting:'Подключение…',connected:'Подключено',retrying:'Ожидание переподключения',stopping:'Отключение…'};
function mode(){ $('passwordBlock').classList.toggle('hide',$('auth').value!=='password');$('keyBlock').classList.toggle('hide',$('auth').value!=='key'); } $('auth').addEventListener('change',mode);
async function request(path,obj){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(obj)});if(!r.ok)throw new Error(await r.text());return r.json();}
function msg(text,good=false){$('message').className=good?'success':'error';$('message').textContent=text;}
async function refresh(){try{const r=await fetch('/api/status');if(!r.ok)return;const d=await r.json();$('status').textContent=labels[d.status]||d.status;$('status').className='badge '+d.status;$('lastError').textContent=d.error||'';$('start').disabled=d.running;$('stop').disabled=!d.running;$('save').disabled=d.running;$('scan').disabled=d.running;if(!loaded){for(const k of fields){if(d.config[k]!==undefined && !['password','privateKey','keyPassphrase','certificate'].includes(k))$(k).value=d.config[k]};$('autostart').checked=d.config.autostart;$('reconnect').checked=d.config.reconnect;if(d.passwordSaved)$('password').placeholder='Пароль сохранён';if(d.keySaved)$('privateKey').placeholder='Ключ сохранён';if(d.certificateSaved)$('certificate').placeholder='Сертификат сохранён';mode();loaded=true}}catch(e){$('status').textContent='Нет связи с приложением';$('status').className='badge error'}}
$('save').onclick=async()=>{let c={};for(const k of fields)c[k]=['password','keyPassphrase','privateKey','certificate'].includes(k)?$(k).value:$(k).value.trim();c.port=Number(c.port);c.socksPort=Number(c.socksPort);c.autostart=$('autostart').checked;c.reconnect=$('reconnect').checked;try{await request('/api/save',c);for(const k of ['password','privateKey','keyPassphrase','certificate'])$(k).value='';msg('Настройки сохранены',true);loaded=false;await refresh()}catch(e){msg(e.message)}};
$('start').onclick=async()=>{try{await request('/api/command',{action:'start'});await refresh()}catch(e){msg(e.message)}};$('stop').onclick=async()=>{try{await request('/api/command',{action:'stop'});await refresh()}catch(e){msg(e.message)}};
$('scan').onclick=async()=>{let target=$('keys');target.replaceChildren();try{const keys=await request('/api/scan',{host:$('host').value.trim(),port:Number($('port').value)});for(const k of keys){const div=document.createElement('div');div.className='key';const txt=document.createElement('span');txt.className='mono';txt.textContent=k.fingerprint;const b=document.createElement('button');b.className='secondary';b.type='button';b.textContent='Выбрать';b.onclick=()=>{$('hostKey').value=k.key;msg('Сравните отпечаток с доверенным источником и введите его вручную.')};div.append(txt,b);target.append(div)}}catch(e){msg(e.message)}};
refresh();setInterval(refresh,3000);
</script></body></html>`
